'use strict';
/* Art: every picture in the game is a small piece of SVG. The interface uses it directly,
   the map turns each piece into a bitmap once (see render.js) and then only copies it. */

/* Hand-made shapes for the art: loops that waver, stones of uneven size, grass at the edge */
const wob = (rx, ry, seed, j = .1, n = 12, cx = 0, cy = 0) => wobble(cx, cy, rx, ry, seed, j, n).d;
const stoneAt = (x, y, s, seed, fill = '#8E8A80') => `<path d="${wob(1.3 * s, .85 * s, seed, .2, 7, x, y)}" fill="${fill}" stroke="#2B1D14" stroke-width=".4"/>`;
function stonesAround(rx, ry, n, seed, s = 1, fill){ const r = rng(seed); let h = ''; for (let i = 0; i < n; i++){ const a = i / n * TAU + (r() - .5) * .5, k = .9 + r() * .18; h += stoneAt(Math.cos(a) * rx * k, Math.sin(a) * ry * k, s * (.65 + r() * .7), seed + i * 7, fill); } return h; }
const scuffs = (seed, rx, ry, n = 5) => { const r = rng(seed); let d = ''; for (let i = 0; i < n; i++){ const x = (r() - .5) * 1.4 * rx, y = (r() - .5) * 1.4 * ry, l = 1.6 + r() * 2.4; d += `M${fx(x)} ${fx(y)}q${fx(l / 2)} ${fx(-.5 - r() * .4)} ${fx(l)} 0`; } return `<path d="${d}" fill="none" stroke="#A88C58" stroke-width=".5" stroke-linecap="round"/>`; };
const FIELD = (inner, seed) => `<path d="${wob(10.8, 6.6, seed, .1, 12)}" fill="#A48A57" stroke="#6B5030" stroke-width=".5"/><path d="${wob(9, 5.1, seed + 2, .12, 12)}" fill="${inner}"/>`;
