const ROOF_NEW = '#DDB060', ROOF_OLD = '#8F8574';

/* The interface (build buttons, goods row) references the art by id, so it goes into one hidden <defs> */
function patDef(id){ const [w, h, body] = PAT[id]; return `<pattern id="${id}" width="${w}" height="${h}" patternUnits="userSpaceOnUse">${body}</pattern>`; }
function injectDefs(){
  const s = document.createElementNS(NS, 'svg');
  s.setAttribute('width', '0'); s.setAttribute('height', '0'); s.setAttribute('aria-hidden', 'true'); s.setAttribute('focusable', 'false');
  s.style.cssText = 'position:absolute;left:0;top:0;overflow:hidden';
  s.innerHTML = '<defs>' + Object.keys(PAT).map(patDef).join('') + Object.entries(SYM).map(([k, v]) => `<g id="${k}">${v}</g>`).join('') + '</defs>';
  document.body.prepend(s);
  return s;
}
/* A stand-alone SVG needs its own copies of everything it references */
function deps(str, out = new Set()){
  for (const m of str.matchAll(/href="#([\w-]+)"|url\(#([\w-]+)\)/g)){
    const id = m[1] || m[2]; if (out.has(id)) continue; out.add(id); if (SYM[id]) deps(SYM[id], out); else if (PAT[id]) deps(PAT[id][2], out);
  }
  return out;
}
function defsFor(str){ let s = ''; for (const id of deps(str)) s += SYM[id] ? `<g id="${id}">${SYM[id]}</g>` : PAT[id] ? patDef(id) : ''; return s; }

/* Something stands by most houses: firewood, a pot, a mat drying in the sun, an earth oven covered with leaves */
